-- Tables of the ricorsa store the portfolio adapter reads (DDL as in production), with fixture rows.
CREATE TABLE IF NOT EXISTS `users` ( `id` text PRIMARY KEY NOT NULL, `email` text, `name` text, `picture` text, `plan` text DEFAULT 'free' NOT NULL, `paypal_subscription_id` text, `subscription_status` text, `plan_renews_at` integer, `settings` text DEFAULT '{}' NOT NULL, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `last_seen_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `billing_cycle` text, `allowance` text, `gas_balance` integer DEFAULT 0 NOT NULL, `subscription_provider` text, `finix_identity_id` text, `welcome_gas_at` integer, `finix_instrument_id` text, `card_brand` text, `card_last_four` text, `auto_recharge` integer DEFAULT false NOT NULL, `auto_recharge_threshold` integer DEFAULT 200 NOT NULL, `auto_recharge_usd` integer DEFAULT 20 NOT NULL, `auto_recharge_failures` integer DEFAULT 0 NOT NULL, `auto_recharge_last_at` integer, `recharge_agreed_at` integer, `recharge_agreement_version` text);
CREATE TABLE IF NOT EXISTS `subscriptions` ( `id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `plan_key` text NOT NULL, `paypal_plan_id` text NOT NULL, `status` text NOT NULL, `started_at` integer, `next_billing_at` integer, `cancelled_at` integer, `raw` text, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `billing_cycle` text, `provider` text DEFAULT 'paypal' NOT NULL );
CREATE TABLE IF NOT EXISTS `usage` ( `user_id` text NOT NULL, `period` text NOT NULL, `questions` integer DEFAULT 0 NOT NULL, `research` integer DEFAULT 0 NOT NULL, `tokens_in` integer DEFAULT 0 NOT NULL, `tokens_out` integer DEFAULT 0 NOT NULL, `searches` integer DEFAULT 0 NOT NULL, `cost_micros` integer DEFAULT 0 NOT NULL, `builds` integer DEFAULT 0 NOT NULL, `ideas` integer DEFAULT 0 NOT NULL, `browser_actions` integer DEFAULT 0 NOT NULL, `gas` integer DEFAULT 0 NOT NULL, PRIMARY KEY(`user_id`, `period`) );
CREATE TABLE IF NOT EXISTS `gas_purchases` ( `id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `order_id` text NOT NULL, `usd_cents` integer NOT NULL, `gas` integer NOT NULL, `status` text DEFAULT 'completed' NOT NULL, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `provider` text DEFAULT 'paypal' NOT NULL, `kind` text DEFAULT 'recharge' NOT NULL, `agreement_version` text );
CREATE TABLE IF NOT EXISTS `threads` ( `id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `space_id` text, `title` text NOT NULL, `turns` text DEFAULT '[]' NOT NULL, `origin` text, `turn_count` integer DEFAULT 0 NOT NULL, `snippet` text DEFAULT '' NOT NULL, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL );
